Add-Type @"
using System;
using System.Runtime.InteropServices;
public class DllLoader2 {
    [DllImport\("kernel32.dll", SetLastError=true\)]
    public static extern IntPtr LoadLibraryEx\(string lpFileName, IntPtr hFile, uint dwFlags\);
    [DllImport\("kernel32.dll", SetLastError=true\)]
    public static extern bool FreeLibrary\(IntPtr hModule\);
}
"@

$libdir = "C:\\OpenFOAM\\SPUMA\\platforms\\win64MsvcSyclDPInt32Opt\\lib"
$handles = @\(\)

# Load in dependency order
$deps = @\("libOpenFOAM.dll","libfileFormats.dll","libsurfMesh.dll","libmeshTools.dll","libfiniteVolume.dll"\)
foreach \($dll in $deps\) {
    $h = [DllLoader2]::LoadLibraryEx\("$libdir\\$dll", [IntPtr]::Zero, 0x00000008\)
    if \($h -eq [IntPtr]::Zero\) {
        $err = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error\(\)
        Write-Host "FAIL loading dep: $dll \(error=$err\)"
        exit 1
    }
    $handles += $h
    Write-Host "Loaded dep: $dll"
}

# Now try dynamicMesh
Write-Host "--- Now loading libdynamicMesh.dll ---"
$h = [DllLoader2]::LoadLibraryEx\("$libdir\\libdynamicMesh.dll", [IntPtr]::Zero, 0x00000008\)
if \($h -eq [IntPtr]::Zero\) {
    $err = [System.Runtime.InteropServices.Marshal]::GetLastWin32Error\(\)
    Write-Host "FAIL: libdynamicMesh.dll \(error=$err\)"
} else {
    Write-Host "OK: libdynamicMesh.dll"
    [DllLoader2]::FreeLibrary\($h\) | Out-Null
}

# Cleanup
foreach \($h in $handles\) { [DllLoader2]::FreeLibrary\($h\) | Out-Null }
PSEOF)
